#include "orbit.h"
#include "split_util.h"

void led_init_ports(void) {
    // Initialize indicator LEDs to output
    if (is_keyboard_left()) {
        gpio_set_pin_output(C6);
        gpio_set_pin_output(B6);
        gpio_set_pin_output(B5);
    } else {
        gpio_set_pin_output(F6);
        gpio_set_pin_output(F7);
        gpio_set_pin_output(C7);
    }

    set_layer_indicators(0);
}

// Call led_toggle to set LEDs easily
// LED IDs:
//
// (LEFT) 0 1 2   |   3 4 5 (RIGHT)
void led_toggle(uint8_t id, bool on) {
    if (is_keyboard_left()) {
        switch (id) {
            case 0:
                // Left hand C6
                gpio_write_pin(C6, on);
                break;
            case 1:
                // Left hand B6
                gpio_write_pin(B6, on);
                break;
            case 2:
                // Left hand B5
                gpio_write_pin(B5, on);
                break;
            default:
                break;
        }
    } else {
        switch (id) {
            case 3:
                // Right hand F6
                gpio_write_pin(F6, on);
                break;
            case 4:
                // Right hand F7
                gpio_write_pin(F7, on);
                break;
            case 5:
                // Right hand C7
                gpio_write_pin(C7, on);
                break;
            default:
                break;
        }
    }
}

// Set all LEDs at once using an array of 6 booleans
// LED IDs:
//
// (LEFT) 0 1 2   |   3 4 5 (RIGHT)
//
// Ex. set_all_leds({ false, false, false, true, true, true }) would turn off left hand, turn on right hand

void set_all_leds(bool leds[6]) {
    for (int i = 0; i < 6; i++) {
        led_toggle(i, leds[i]);
    }
}

void set_layer_indicators(uint8_t layer) {
    switch (layer) {
        case 0:
            led_toggle(0, true);
            led_toggle(1, false);
            led_toggle(2, false);
            break;
        case 1:
            led_toggle(0, true);
            led_toggle(1, true);
            led_toggle(2, false);
            break;
        case 2:
            led_toggle(0, true);
            led_toggle(1, true);
            led_toggle(2, true);
            break;
        case 3:
            led_toggle(0, false);
            led_toggle(1, true);
            led_toggle(2, true);
            break;
        case 4:
            led_toggle(0, false);
            led_toggle(1, false);
            led_toggle(2, true);
            break;
        default:
            led_toggle(0, true);
            led_toggle(1, false);
            led_toggle(2, true);
            break;
    }
}

bool led_update_kb(led_t led_state) {
    bool res = led_update_user(led_state);
    if (res) {
        led_toggle(3, led_state.num_lock);
        led_toggle(4, led_state.caps_lock);
        led_toggle(5, led_state.scroll_lock);
    }
    return res;
}

layer_state_t layer_state_set_kb(layer_state_t state) {
    set_layer_indicators(get_highest_layer(state));

    return layer_state_set_user(state);
}

