bool process_record_user(uint16_t keycode, keyrecord_t *record) {
	switch (keycode) {
		case MANUAL:
			if (record->event.pressed) {
				SEND_STRING("https://kb.ai03.me/redir/orbit");
			}
			break;
		case DBLZERO:
			if (record->event.pressed) {
				SEND_STRING("00");
			}
			break;
  }
  return true;
}
